// มองย้อนหลัง 65 นาที (เผื่อเหลื่อม 5 นาทีจากรอบก่อน — ยิงซ้ำได้ปลอดภัย เพราะ
// upsert_event กันแถวซ้ำฝั่ง DB ด้วย unique index line_uid+date+occasion อยู่แล้ว)
const since = new Date(Date.now() - 65 * 60 * 1000).toISOString();
return [{ json: { since } }];

// ⚠️ TODO: แก้ mapping ให้ตรง schema จริงของ booking กลุ่ม (ตอนนี้เดาโครงไว้)
// เป้าหมาย: 1 item ต่อแขก 1 คน = { line_uid, date (YYYY-MM-DD), occasion }
// ฝั่งหน้าเว็บ (group-checkout.html → saveGroupCalendar) บันทึกให้เฉพาะ "หัวหน้ากลุ่ม" แล้ว
// job นี้เก็บตกสมาชิกที่เหลือของกลุ่มที่มี line_uid
const out = [];
for (const item of $input.all()) {
  const b = item.json;
  const members  = b.members || b.group_members || [];        // TODO: ชื่อฟิลด์รายชื่อสมาชิกจริง
  const date     = b.event_date || b.date;                    // TODO: ชื่อฟิลด์วันงานจริง
  const occasion = b.occasion || 'party';                     // TODO: ชื่อฟิลด์ occasion จริง
  if (!date) continue;
  for (const m of members) {
    const uid = typeof m === 'string' ? m : (m && (m.line_uid || m.uid));
    if (uid) out.push({ json: { line_uid: uid, date, occasion } });
  }
}
return out; // ว่าง = ชั่วโมงนี้ไม่มี booking กลุ่มใหม่

function bubble(title, body, btnLabel, uri, extra) {
  const bodyContents = [
    { type: 'text', text: title, weight: 'bold', size: 'md', wrap: true, color: '#1F2A22' },
    { type: 'text', text: body, size: 'sm', color: '#6B7A6E', wrap: true }
  ];
  if (extra) bodyContents.push({ type: 'text', text: extra, size: 'xs', color: '#8A9388', wrap: true, margin: 'md' });
  return {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: '#3E5C46', paddingAll: '16px',
      contents: [ { type: 'text', text: 'LLOOP', color: '#FFFFFF', weight: 'bold', size: 'sm' } ] },
    body: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '20px', contents: bodyContents },
    footer: { type: 'box', layout: 'vertical', paddingAll: '16px',
      contents: [ { type: 'button', style: 'primary', color: '#3E5C46', height: 'sm',
        action: { type: 'uri', label: btnLabel, uri: uri } } ] }
  };
}

// สร้างข้อความ LINE ต่อแขก 1 คน (uid จาก node แปลง booking — n8n จับคู่ item ให้)
const guest = $('⚠️ TODO: แปลง booking → รายชื่อแขก (แก้ชื่อฟิลด์)').item.json;
const title = 'วันงานถูกบันทึกลงปฏิทินแล้วค่ะ';
const bodyText = 'สไตลิสต์จะเตรียมลุคให้ก่อนถึงวันงานนะคะ แตะดู/แก้รายละเอียดงานได้เลยค่ะ';
const contents = bubble(title, bodyText, 'ดูปฏิทินของฉัน',
                        'https://wearlloop-dotcom.github.io/my-events.html');
return { json: { lineBody: { to: guest.line_uid, messages: [{ type: 'flex',
  altText: 'วันงานถูกบันทึกลงปฏิทินแล้ว สไตลิสต์จะเตรียมลุคให้ก่อนถึงวันค่ะ', contents }] } } };
